/**
 * Retourne l'asset SVG Data URL embarqué pour un bioagresseur donné.
 * Garanti d'afficher une illustration vectorielle propre en toute circonstance.
 */
export function getEmbeddedPestSvg(pestIdOrKey: string, category?: string): string {
  const id = pestIdOrKey.toLowerCase();

  if (id.includes('cloque')) return PHYTO_DATA_ASSETS['cloque'] || '';
  if (id.includes('tavelure')) return PHYTO_DATA_ASSETS['tavelure'] || '';
  if (id.includes('feu_bacterien') || id.includes('erwinia')) return PHYTO_DATA_ASSETS['feu_bacterien'] || '';
  if (id.includes('monilia') || id.includes('moniliose')) return PHYTO_DATA_ASSETS['moniliose'] || '';
  if (id.includes('carpocapse')) return PHYTO_DATA_ASSETS['carpocapse'] || '';
  if (id.includes('oeil_paon')) return PHYTO_DATA_ASSETS['oeil_paon'] || '';
  if (id.includes('mouche') && id.includes('oli')) return PHYTO_DATA_ASSETS['mouche_olive'] || '';
  if (id.includes('ceratite') || (id.includes('mouche') && !id.includes('oli'))) return PHYTO_DATA_ASSETS['ceratite'] || '';
  if (id.includes('tuberculose') || id.includes('chancre')) return PHYTO_DATA_ASSETS['tuberculose'] || '';
  if (id.includes('oidium')) return PHYTO_DATA_ASSETS['oidium'] || '';
  if (id.includes('coryneum') || id.includes('rouille')) return PHYTO_DATA_ASSETS['coryneum'] || '';
  if (id.includes('puceron')) return PHYTO_DATA_ASSETS['puceron'] || '';
  if (id.includes('acarien') || id.includes('tetranyque')) return PHYTO_DATA_ASSETS['acarien'] || '';
  if (id.includes('cochenille')) return PHYTO_DATA_ASSETS['cochenille'] || '';
  if (id.includes('psylle')) return PHYTO_DATA_ASSETS['psylle'] || '';
  if (id.includes('anthracnose')) return PHYTO_DATA_ASSETS['anthracnose'] || '';
  if (id.includes('thrips') || id.includes('mineuse') || id.includes('tordeuse') || id.includes('anthonome') || id.includes('capnode')) {
    return PHYTO_DATA_ASSETS['thrips'] || '';
  }

  if (category === 'champignon') return PHYTO_DATA_ASSETS['tavelure'] || '';
  if (category === 'bacterie') return PHYTO_DATA_ASSETS['feu_bacterien'] || '';
  if (category === 'acarien') return PHYTO_DATA_ASSETS['acarien'] || '';
  return PHYTO_DATA_ASSETS['puceron'] || '';
}
